import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../store/authStore';
import { Box, Typography, TextField, Button, Paper } from '@mui/material';
import { getGraphQLErrorMessage } from '../../utils/graphqlErrors';
import { loginSchema, LoginFormData } from '../../validation/schemas';

export default function LoginFormComponent() {
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<LoginFormData>({
    resolver: zodResolver(loginSchema),
  });
  const [error, setError] = useState('');
  const { login } = useAuth();
  const navigate = useNavigate();

  const onSubmit = async (data: LoginFormData) => {
    try {
      await login(data.email, data.password);
      navigate('/dashboard');
    } catch (err) {
      setError(getGraphQLErrorMessage(err, 'Login failed'));
    }
  };

  return (
    <Box className="max-w-md mx-auto mt-20">
      <Paper className="p-5 rounded-xl">
        <Typography variant="h4" className="text-2xl font-bold mb-4">
          Login
        </Typography>
        {error && <Typography className="text-red-600 mb-2">{error}</Typography>}
        <form onSubmit={handleSubmit(onSubmit)}>
          <TextField
            fullWidth
            type="email"
            placeholder="Email"
            {...register('email')}
            error={!!errors.email}
            helperText={errors.email?.message}
            margin="normal"
          />
          <TextField
            fullWidth
            type="password"
            placeholder="Password"
            {...register('password')}
            error={!!errors.password}
            helperText={errors.password?.message}
            margin="normal"
          />
          <Button
            type="submit"
            fullWidth
            variant="contained"
            className="w-full p-3 !bg-[#e94560] hover:!bg-[#d63d54] !text-white normal-case mt-4"
          >
            Login
          </Button>
        </form>
      </Paper>
      {/* <Typography className="mt-2">
        Don't have an account?{' '}
        <Link to="/register" className="text-[#e94560]">
          Register
        </Link>
      </Typography> */}
    </Box>
  );
}
